package com.andye.warmod.radar.client;
import com.andye.warmod.icbm.IcbmTrajectory;import com.andye.warmod.radar.*;import com.andye.warmod.warhead.WarheadTrajectory;import java.util.UUID;import net.minecraft.world.phys.Vec3;
public final class ClientRadarTrack{private RadarTrackSnapshot snapshot;public ClientRadarTrack(RadarTrackSnapshot s){snapshot=s;}public void update(RadarTrackSnapshot s){snapshot=s;}public RadarTrackSnapshot snapshot(){return snapshot;}public UUID id(){return snapshot.trackId();}public Vec3 position(double time){if(snapshot.phase()==RadarTrackPhase.IMPACT)return target();if(snapshot.terminalPlan().isPresent()){RadarTerminalPlanSnapshot p=snapshot.terminalPlan().get();return WarheadTrajectory.position(p.startPosition(),p.targetPosition(),Math.max(0,time-p.launchGameTime()),p.flightTicks());}if(snapshot.carrierPlan().isPresent()){RadarCarrierPlanSnapshot p=snapshot.carrierPlan().get();return IcbmTrajectory.position(asPlan(p),Math.max(0,time-p.launchGameTime()));}return Vec3.ZERO;}public Vec3 velocity(double time){if(snapshot.terminalPlan().isPresent()){RadarTerminalPlanSnapshot p=snapshot.terminalPlan().get();return WarheadTrajectory.velocity(p.startPosition(),p.targetPosition(),Math.max(0,time-p.launchGameTime()),p.flightTicks());}if(snapshot.carrierPlan().isPresent()){RadarCarrierPlanSnapshot p=snapshot.carrierPlan().get();return IcbmTrajectory.velocity(asPlan(p),Math.max(0,time-p.launchGameTime()));}return Vec3.ZERO;}public Vec3 target(){return snapshot.terminalPlan().map(RadarTerminalPlanSnapshot::targetPosition).orElseGet(()->snapshot.carrierPlan().map(RadarCarrierPlanSnapshot::intendedTarget).orElse(Vec3.ZERO));}public Vec3 launch(){return snapshot.carrierPlan().map(RadarCarrierPlanSnapshot::launchPosition).orElseGet(()->snapshot.terminalPlan().map(RadarTerminalPlanSnapshot::startPosition).orElse(Vec3.ZERO));}private com.andye.warmod.icbm.IcbmFlightPlan asPlan(RadarCarrierPlanSnapshot p){return new com.andye.warmod.icbm.IcbmFlightPlan(snapshot.trackId(),snapshot.ownerPlayerId(),p.launchPosition(),p.burnoutPosition(),p.separationPosition(),p.intendedTarget(),p.launchGameTime(),p.ignitionTicks(),p.boostTicks(),p.coastTicks(),p.visualSeed(),snapshot.payloadType());}}
